/bin/bash -lc "cat > /tmp/gbrain-install-docs/mcp-check.mjs <<'JS'
import fs from 'node:fs';
import { Client } from '/harness-state/.bun/install/global/node_modules/gbrain/node_modules/@modelcontextprotocol/sdk/dist/esm/client/index.js';
import { StdioClientTransport } from '/harness-state/.bun/install/global/node_modules/gbrain/node_modules/@modelcontextprotocol/sdk/dist/esm/client/stdio.js';
const config = Bun.TOML.parse(fs.readFileSync('/harness-state/codex/config.toml','utf8')).mcp_servers.gbrain;
const transport = new StdioClientTransport({command:config.command,args:config.args,env:{...process.env,...config.env},stderr:'inherit'});
const client=new Client({name:'gbrain-install-check',version:'1.0.0'});
try {
 await client.connect(transport);
 const action=process.argv[2];
 const result=action==='list'?await client.listTools():await client.callTool({name:action,arguments:JSON.parse(process.argv[3]||'{}')});
 console.log(JSON.stringify(result,null,2));
 if(result.isError) process.exitCode=1;
} finally { await client.close(); }
JS
